let defaultDocsifyUpdatedOptions = {
  text: ">Last Modify: {docsify-updated}",
  formatUpdated: "{YYYY}/{MM}/{DD}",
  whereToPlace: "bottom"
};

// 简易日期格式化函数
function formatDate(date, fmt) {
  const YYYY = date.getFullYear();
  const MM = String(date.getMonth() + 1).padStart(2, '0');
  const DD = String(date.getDate()).padStart(2, '0');
  return fmt.replace('{YYYY}', YYYY)
            .replace('{MM}', MM)
            .replace('{DD}', DD);
}

function plugin(hook, vm) {
  hook.beforeEach(function (markdown) {
    const cfg = vm.config.timeUpdater || defaultDocsifyUpdatedOptions;
    let text = cfg.text;
    const pos = String(cfg.whereToPlace ?? "bottom").toLowerCase();
    const nowStr = formatDate(new Date(), cfg.formatUpdated);
    text = text.replace('{docsify-updated}', nowStr);

    if (pos === "top") {
      return text + "\n\n" + markdown;
    } else {
      return markdown + "\n\n" + text;
    }
  })
}

window.$docsify = window.$docsify || {};
window.$docsify.timeUpdater = Object.assign({}, defaultDocsifyUpdatedOptions, window.$docsify.timeUpdater || {});
window.$docsify.plugins = (window.$docsify.plugins || []).concat(plugin);